function previewQuiz(qid,quizType=""){$("#sitename").length&&$("#general-id").length&&(sitename=$("#sitename").val(),generalId=$("#general-id").val());var gets,url="/pages/user/qbank-viewer.php?"+["quiz-type="+quizType,"i="+qid,"s="+sitename,"g="+generalId].join("&"),w=$(window).width()-.3*$(window).width(),h=$(window).height()-1*$(window).height(),dualScreenLeft=void 0!==window.screenLeft?window.screenLeft:screen.left,dualScreenTop=void 0!==window.screenTop?window.screenTop:screen.top,width,height,left=(window.innerWidth?window.innerWidth:document.documentElement.clientWidth?document.documentElement.clientWidth:screen.width)/2-w/2+dualScreenLeft,top=(window.innerHeight?window.innerHeight:document.documentElement.clientHeight?document.documentElement.clientHeight:screen.height)/2-h/2+dualScreenTop;preview=window.open(url,"Quiz viewer","menubar=no,scrollbars=yes,toolbar=no,location=no,resizable=yes, width="+w+", height="+h+", top="+top+", left="+left),preview||alert("You must allow popups for this preview to work.")}